ON CONFLICT(slug) DO UPDATE SET name=excluded.name,description=excluded.description,category=excluded.category,duration_minutes=excluded.duration_minutes,configuration_json=excluded.configuration_json,source_name=excluded.source_name,source_updated_month=excluded.source_updated_month,updated_at=CURRENT_TIMESTAMP;

INSERT OR IGNORE INTO service_template_versions(service_template_id,version,change_summary,snapshot_json,created_at)
SELECT id,1,'Importação inicial da fonte','{}',CURRENT_TIMESTAMP FROM service_templates;

CREATE TEMP TABLE IF NOT EXISTS seed_service_components(service_slug TEXT,component_name TEXT,category TEXT,included INTEGER,optional INTEGER,configurable INTEGER,sort_order INTEGER,configuration_json TEXT,notes TEXT);
DELETE FROM seed_service_components;

INSERT OR IGNORE INTO service_components(slug,name,description,category,source_label,normalized_name,search_aliases,configurable,active,created_at,updated_at)
SELECT 'component-'||lower(hex(component_name)),component_name,'',category,component_name,component_name,'',MAX(configurable),1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM seed_service_components GROUP BY component_name,category;

INSERT OR IGNORE INTO service_template_components(service_template_id,service_component_id,sort_order,included,optional,configuration_json,notes,active,created_at,updated_at)
SELECT service.id,component.id,data.sort_order,data.included,data.optional,data.configuration_json,data.notes,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM seed_service_components data JOIN service_templates service ON service.slug=data.service_slug JOIN service_components component ON component.slug='component-'||lower(hex(data.component_name));

INSERT OR IGNORE INTO service_choice_groups(service_template_id,slug,name,selection_min,selection_max,selection_required,configurable,created_at,updated_at)
SELECT id,'tipo-de-cerimonia','Tipo de cerimônia',1,1,1,0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM service_templates WHERE slug='celebrante';
INSERT OR IGNORE INTO service_choice_group_components(service_choice_group_id,service_template_component_id,sort_order,created_at)
SELECT choice.id,link.id,link.sort_order,CURRENT_TIMESTAMP FROM service_choice_groups choice JOIN service_templates service ON service.id=choice.service_template_id JOIN service_template_components link ON link.service_template_id=service.id JOIN service_components component ON component.id=link.service_component_id WHERE service.slug='celebrante' AND component.name IN ('Cerimônia sem efeito civil','Cerimônia com efeito civil');

DROP TABLE seed_service_components;
